package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime;
@Document(collection="inventory_alerts") public class InventoryAlert { @Id private String id; private String productId; private String warehouseId; private AlertType type; private String severity; private String message; private boolean acknowledged; private LocalDateTime createdAt=LocalDateTime.now(); public InventoryAlert(){} public String getId(){return id;} public void setId(String v){id=v;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public AlertType getType(){return type;} public void setType(AlertType v){type=v;} public String getSeverity(){return severity;} public void setSeverity(String v){severity=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public boolean isAcknowledged(){return acknowledged;} public void setAcknowledged(boolean v){acknowledged=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} }
